-- Aprenda se Divertindo · 115 · Trilha Policial · lote extra 18 (200 questões de todos os níveis)
-- Rode depois do 114-trilha-policial-17.sql. Cole tudo no SQL Editor e clique em Run. Rodar de novo apenas atualiza.
-- Números 10747 a 10946: 40 de cada nível (0 a 4), quase todas em forma de caso prático,
-- com alternativas erradas do mesmo assunto e de tamanho parecido com a certa.

insert into public.questoes (id, materia, nivel, enunciado, opcoes, explicacao)
select id, materia, nivel, enunciado, opcoes, explicacao
from jsonb_to_recordset($q$[{"id": 10747, "materia": "pen", "nivel": 0, "enunciado": "Carlos entrou numa loja e, sem ninguém ver, pôs um celular no bolso e saiu. Ele cometeu:", "opcoes": ["Furto", "Roubo", "Estelionato", "Apropriação indébita"], "explicacao": "Subtrair coisa alheia móvel sem violência ou grave ameaça é furto (art. 155 do CP)."}, {"id": 10748, "materia": "pen", "nivel": 0, "enunciado": "Marta apontou uma faca para uma senhora e levou sua bolsa. O crime é:", "opcoes": ["Roubo", "Furto", "Extorsão", "Dano"], "explicacao": "A grave ameaça para subtrair caracteriza roubo (art. 157 do CP)."}, {"id": 10749, "materia": "pen", "nivel": 1, "enunciado": "Pedro achou uma carteira na rua e ficou com ela sem procurar o dono nem entregá-la à autoridade em 15 dias. Ele pratica:", "opcoes": ["Apropriação de coisa achada", "Furto qualificado por destreza", "Estelionato", "Receptação"], "explicacao": "Art. 169, parágrafo único, II, do CP."}, {"id": 10750, "materia": "pen", "nivel": 1, "enunciado": "Lúcia comprou uma TV sabendo que era roubada, por um preço bem abaixo do mercado. Ela responde por:", "opcoes": ["Receptação", "Furto", "Favorecimento pessoal", "Roubo"], "explicacao": "Adquirir coisa que sabe ser produto de crime é receptação (art. 180 do CP)."}, {"id": 10751, "materia": "pen", "nivel": 2, "enunciado": "João matou o pai colocando veneno no café. Qual qualificadora do homicídio está presente?", "opcoes": ["Emprego de veneno", "Emboscada contra a vítima", "Asfixia", "Motivo fútil"], "explicacao": "Art. 121, § 2º, III, do CP: veneno é meio qualificador."}, {"id": 10752, "materia": "pen", "nivel": 1, "enunciado": "Uma policial exigiu R$ 500 de um motorista para não autuá-lo. Ela cometeu:", "opcoes": ["Concussão", "Corrupção passiva", "Prevaricação", "Peculato"], "explicacao": "Exigir vantagem indevida em razão da função é concussão (art. 316 do CP)."}, {"id": 10753, "materia": "pen", "nivel": 2, "enunciado": "Um servidor aceitou, sem ter pedido, dinheiro de um empresário para agilizar um processo. Ele cometeu:", "opcoes": ["Corrupção passiva", "Concussão", "Corrupção ativa", "Advocacia administrativa"], "explicacao": "Receber ou aceitar promessa de vantagem indevida é corrupção passiva (art. 317 do CP)."}, {"id": 10754, "materia": "pen", "nivel": 3, "enunciado": "Rui, tesoureiro da prefeitura, desviou para a própria conta dinheiro público que estava sob sua guarda. O crime é:", "opcoes": ["Peculato", "Concussão", "Apropriação indébita", "Furto qualificado"], "explicacao": "Art. 312 do CP: funcionário que se apropria ou desvia bem que tem a posse em razão do cargo."}, {"id": 10755, "materia": "pen", "nivel": 0, "enunciado": "Bruno atirou para matar Caio, mas errou todos os tiros e ninguém se feriu. Houve:", "opcoes": ["Tentativa de homicídio", "Homicídio consumado", "Fato atípico", "Lesão corporal culposa"], "explicacao": "O crime não se consumou por circunstâncias alheias à vontade do agente (art. 14, II, do CP): tentativa branca."}, {"id": 10756, "materia": "pen", "nivel": 3, "enunciado": "Diego começou a forçar a porta de uma casa para furtar, mas desistiu por conta própria e foi embora. Ele:", "opcoes": ["Responde só pelos atos já praticados", "Responde por tentativa de furto qualificado", "Responde por furto consumado", "Responde por furto com pena dobrada"], "explicacao": "Desistência voluntária (art. 15 do CP): o agente só responde pelos atos já praticados, como o dano à porta."}, {"id": 10757, "materia": "pen", "nivel": 3, "enunciado": "Igor furtou uma bicicleta, sem violência, e a devolveu por vontade própria antes do recebimento da denúncia. Isso é:", "opcoes": ["Arrependimento posterior", "Desistência voluntária", "Arrependimento eficaz", "Crime impossível"], "explicacao": "Art. 16 do CP: a pena é reduzida de 1/3 a 2/3."}, {"id": 10758, "materia": "pen", "nivel": 4, "enunciado": "Fábio envenenou Gil, mas se arrependeu e lhe deu o antídoto a tempo, e Gil sobreviveu sem sequelas. Fábio:", "opcoes": ["Responde só pelos atos já praticados", "Responde por tentativa de homicídio", "Responde por homicídio com pena reduzida", "Responde por lesão corporal gravíssima"], "explicacao": "Arrependimento eficaz (art. 15 do CP): o agente impede o resultado e só responde pelo que já causou."}, {"id": 10759, "materia": "pen", "nivel": 0, "enunciado": "Na discussão, Paula chamou a vizinha de \"burra e nojenta\". Ofender a dignidade de alguém assim é:", "opcoes": ["Injúria", "Calúnia", "Difamação", "Ameaça"], "explicacao": "Injúria é ofender a dignidade ou o decoro, sem imputar fato (art. 140 do CP)."}, {"id": 10760, "materia": "pen", "nivel": 1, "enunciado": "Tiago contou a colegas, mentindo, que o chefe furtou dinheiro do caixa na sexta-feira. Isso é:", "opcoes": ["Calúnia", "Injúria", "Difamação", "Denunciação caluniosa"], "explicacao": "Imputar falsamente a alguém fato definido como crime é calúnia (art. 138 do CP)."}, {"id": 10761, "materia": "pen", "nivel": 2, "enunciado": "Vera espalhou pelo bairro que a vizinha chega embriagada ao trabalho todos os dias. Esse fato ofensivo, que não é crime, configura:", "opcoes": ["Difamação", "Calúnia", "Injúria", "Ameaça"], "explicacao": "Imputar fato ofensivo à reputação, não criminoso, é difamação (art. 139 do CP)."}, {"id": 10762, "materia": "pen", "nivel": 3, "enunciado": "Ao ser abordado, Hugo deu o nome do irmão aos policiais para esconder que tinha mandado de prisão. Ele cometeu:", "opcoes": ["Falsa identidade", "Falsidade ideológica", "Uso de documento falso", "Favorecimento pessoal"], "explicacao": "Art. 307 do CP. A Súmula 522 do STJ diz que é crime mesmo em autodefesa."}, {"id": 10763, "materia": "pen", "nivel": 1, "enunciado": "Leo emprestou o carro a um amigo, que o vendeu e ficou com o dinheiro. O amigo cometeu:", "opcoes": ["Apropriação indébita", "Furto", "Estelionato", "Receptação"], "explicacao": "Ele já tinha a posse lícita do carro e passou a agir como dono (art. 168 do CP)."}, {"id": 10764, "materia": "pen", "nivel": 3, "enunciado": "Nina ligou para um idoso fingindo ser do banco e o convenceu a transferir dinheiro para a conta dela. O crime é:", "opcoes": ["Estelionato, com pena aumentada", "Furto mediante fraude, com pena simples", "Extorsão, com pena aumentada", "Apropriação indébita, simples"], "explicacao": "A vítima entregou o dinheiro enganada (art. 171 do CP); contra idoso a pena aumenta (§ 4º)."}, {"id": 10765, "materia": "pen", "nivel": 4, "enunciado": "Num roubo, o assaltante usou um revólver de uso permitido para ameaçar a vítima. A pena:", "opcoes": ["Aumenta de 2/3", "Aumenta de 1/3 até a metade", "É aplicada em dobro", "Aumenta de 1/6"], "explicacao": "Art. 157, § 2º-A, I, do CP. Se a arma for de uso restrito ou proibido, a pena é dobrada (§ 2º-B)."}, {"id": 10766, "materia": "pen", "nivel": 4, "enunciado": "Para levar o carro, o assaltante atirou e matou o motorista. O crime é julgado:", "opcoes": ["Pelo juiz singular, por ser latrocínio", "Pelo júri, por ser homicídio qualificado", "Pelo júri, em concurso com o roubo", "Pelo júri, por ser crime contra a vida"], "explicacao": "Latrocínio é crime contra o patrimônio; a Súmula 603 do STF afasta o júri."}, {"id": 10767, "materia": "pen", "nivel": 1, "enunciado": "Henrique dirigia com todo o cuidado quando um pedestre se jogou de repente na frente do carro e morreu. Sem dolo nem culpa:", "opcoes": ["Não há crime", "Há homicídio culposo", "Há homicídio doloso", "Há lesão corporal grave"], "explicacao": "Sem dolo ou culpa não há conduta típica (art. 18 do CP)."}, {"id": 10768, "materia": "pen", "nivel": 0, "enunciado": "Kelly, atacada com uma faca, defendeu-se com um pedaço de madeira, usando moderadamente o meio necessário. Ela agiu em:", "opcoes": ["Legítima defesa", "Estado de necessidade", "Estrito cumprimento do dever legal", "Exercício regular de direito"], "explicacao": "Art. 25 do CP: repelir injusta agressão, atual ou iminente, com moderação."}, {"id": 10769, "materia": "pen", "nivel": 0, "enunciado": "Para escapar de um incêndio, Otto arrombou a porta do apartamento vizinho. Ele agiu em:", "opcoes": ["Estado de necessidade", "Legítima defesa", "Exercício regular de direito", "Estrito cumprimento do dever legal"], "explicacao": "Art. 24 do CP: salvar-se de perigo atual que não provocou."}, {"id": 10770, "materia": "pen", "nivel": 2, "enunciado": "Um policial, cumprindo mandado, algema o preso que tenta fugir. Ele age em:", "opcoes": ["Estrito cumprimento do dever legal", "Estado de necessidade", "Legítima defesa putativa de terceiro", "Exercício regular de direito"], "explicacao": "Art. 23, III, do CP: o agente cumpre um dever imposto pela lei."}, {"id": 10771, "materia": "pen", "nivel": 4, "enunciado": "Sílvio, com 17 anos e 11 meses, atirou em Tito, que só morreu semanas depois, quando Sílvio já tinha 18. Sílvio:", "opcoes": ["É inimputável e responde pelo ECA", "Responde pelo CP, pois a morte veio depois", "Responde pelo CP, com pena reduzida", "Responde pelo CP só por lesão corporal"], "explicacao": "Teoria da atividade (art. 4º do CP): vale o momento da ação. Sílvio era menor."}, {"id": 10772, "materia": "pen", "nivel": 3, "enunciado": "Zé cumpriu pena por furto e, dois anos depois, cometeu outro crime. Ele é:", "opcoes": ["Reincidente", "Primário", "Tecnicamente primário", "Apenas de maus antecedentes"], "explicacao": "A reincidência só deixa de valer 5 anos após o cumprimento ou a extinção da pena (art. 64, I, do CP)."}, {"id": 10773, "materia": "ppen", "nivel": 1, "enunciado": "Rafa roubou uma loja e foi perseguido pela polícia, sem interrupção, até ser preso. O flagrante é:", "opcoes": ["Impróprio", "Próprio", "Presumido", "Preparado"], "explicacao": "Art. 302, III, do CPP: perseguido logo após o crime (quase-flagrante)."}, {"id": 10774, "materia": "ppen", "nivel": 0, "enunciado": "Lia teve o celular furtado e registrou a ocorrência. Quem vai presidir o inquérito do caso na delegacia é o:", "opcoes": ["Delegado", "Promotor", "Juiz", "Escrivão"], "explicacao": "O inquérito é conduzido pela autoridade policial (Lei 12.830/2013)."}, {"id": 10775, "materia": "ppen", "nivel": 1, "enunciado": "Pouco depois de um furto, Davi foi encontrado com o celular furtado na mochila e preso em flagrante. Esse flagrante é:", "opcoes": ["Presumido", "Próprio", "Impróprio", "Esperado"], "explicacao": "Art. 302, IV, do CPP: encontrado logo depois com objetos que façam presumir a autoria."}, {"id": 10776, "materia": "ppen", "nivel": 2, "enunciado": "Policiais souberam de uma entrega de drogas e esperaram o momento certo para prender o vendedor, sem induzi-lo a nada. O flagrante é:", "opcoes": ["Esperado, e válido", "Preparado, e nulo", "Forjado, e nulo", "Presumido, e nulo"], "explicacao": "No flagrante esperado a polícia só aguarda o crime acontecer, sem provocá-lo."}, {"id": 10777, "materia": "ppen", "nivel": 2, "enunciado": "Um policial escondeu droga no carro de Elias para prendê-lo em flagrante. Esse flagrante é:", "opcoes": ["Forjado, e ilegal", "Esperado, e válido", "Diferido, e válido", "Impróprio, e válido"], "explicacao": "No flagrante forjado o crime não existiu; quem forjou responde por crime."}, {"id": 10778, "materia": "ppen", "nivel": 1, "enunciado": "Preso em flagrante numa sexta à noite, Fausto deve ser levado à audiência de custódia em até:", "opcoes": ["24 horas", "48 horas", "72 horas", "5 dias"], "explicacao": "Art. 310 do CPP: em até 24 horas após a prisão."}, {"id": 10779, "materia": "ppen", "nivel": 2, "enunciado": "Preso em flagrante por roubo em Feira de Santana, Edu continua na cadeia. O inquérito dele deve terminar, em regra, em:", "opcoes": ["10 dias", "15 dias", "30 dias", "60 dias"], "explicacao": "Art. 10 do CPP: 10 dias com o indiciado preso; 30 se estiver solto."}, {"id": 10780, "materia": "ppen", "nivel": 2, "enunciado": "Sem provas contra o suspeito, o delegado quer arquivar o inquérito. Ele pode?", "opcoes": ["Não, o delegado não pode arquivar", "Sim, se concluir que não há provas suficientes", "Sim, se a vítima concordar", "Sim, depois de 30 dias"], "explicacao": "Art. 17 do CPP: a autoridade policial não pode mandar arquivar autos de inquérito."}, {"id": 10781, "materia": "ppen", "nivel": 4, "enunciado": "Gina foi vítima de injúria e descobriu hoje quem foi o autor. O prazo para oferecer queixa é de:", "opcoes": ["6 meses a partir de hoje", "1 ano a partir do fato", "30 dias a partir de hoje", "2 anos a partir do fato"], "explicacao": "Art. 38 do CPP: decadência em 6 meses, contados de quando souber quem é o autor."}, {"id": 10782, "materia": "ppen", "nivel": 4, "enunciado": "Juca confessou o crime só no inquérito e nenhuma outra prova foi produzida em juízo. O juiz:", "opcoes": ["Não pode condenar só com isso", "Deve condenar pela confissão", "Pode condenar se o delegado depuser", "Deve condenar por ser prova escrita"], "explicacao": "Art. 155 do CPP: não se condena só com elementos informativos da investigação."}, {"id": 10783, "materia": "ppen", "nivel": 1, "enunciado": "A prisão temporária de um suspeito, durante a investigação, é decretada:", "opcoes": ["Pelo juiz", "Pelo delegado", "Pelo promotor", "Pelo chefe de polícia"], "explicacao": "Lei 7.960/1989: o juiz decreta, a pedido do delegado ou do MP."}, {"id": 10784, "materia": "ppen", "nivel": 2, "enunciado": "Num furto qualificado investigado em Salvador, a prisão temporária pode durar:", "opcoes": ["5 dias, prorrogáveis por mais 5", "30 dias, prorrogáveis por mais 30", "10 dias, sem prorrogação", "24 horas, prorrogáveis uma vez"], "explicacao": "Art. 2º da Lei 7.960/1989. Para hediondos o prazo é de 30 + 30 dias."}, {"id": 10785, "materia": "ppen", "nivel": 3, "enunciado": "Kauã é investigado por estupro, crime hediondo. A prisão temporária dele pode durar:", "opcoes": ["30 dias, prorrogáveis por mais 30", "5 dias, prorrogáveis por mais 5", "60 dias, sem prorrogação", "10 dias, prorrogáveis uma única vez"], "explicacao": "Art. 2º, § 4º, da Lei 8.072/1990."}, {"id": 10786, "materia": "ppen", "nivel": 3, "enunciado": "Depois do Pacote Anticrime, o juiz pode decretar a prisão preventiva de ofício, sem pedido de ninguém?", "opcoes": ["Não, nunca de ofício", "Sim, em qualquer fase", "Sim, só no inquérito", "Sim, se o crime for hediondo"], "explicacao": "Art. 311 do CPP: só a requerimento do MP, querelante, assistente ou representação do delegado."}, {"id": 10787, "materia": "ppen", "nivel": 0, "enunciado": "Ao ser preso, Lauro perguntou o que podia fazer. Um direito garantido a ele é:", "opcoes": ["Ficar calado", "Ser solto se pedir", "Escolher a delegacia", "Não ser fotografado"], "explicacao": "Art. 5º, LXIII, da Constituição: direito ao silêncio."}, {"id": 10788, "materia": "ppen", "nivel": 4, "enunciado": "O juiz expediu mandado de busca na casa de Mel. Sem o consentimento dela, o mandado pode ser cumprido:", "opcoes": ["Só durante o dia", "A qualquer hora", "Só com o juiz presente", "Só à noite, de surpresa"], "explicacao": "Art. 5º, XI, da Constituição e art. 245 do CPP."}, {"id": 10789, "materia": "ppen", "nivel": 0, "enunciado": "Caio foi assaltado no ônibus. Concluído o inquérito, quem pode oferecer a denúncia contra o assaltante é o:", "opcoes": ["Ministério Público", "Próprio Caio", "Delegado do caso", "Juiz da comarca"], "explicacao": "Roubo é crime de ação penal pública incondicionada (art. 129, I, da Constituição)."}, {"id": 10790, "materia": "ppen", "nivel": 1, "enunciado": "Rosa foi ameaçada pelo ex-vizinho. Na ameaça comum, o MP só age se houver:", "opcoes": ["Representação da vítima", "Requisição do juiz", "Ordem do delegado", "Prisão do autor"], "explicacao": "Art. 147, parágrafo único, do CP: ação pública condicionada à representação."}, {"id": 10791, "materia": "ppen", "nivel": 4, "enunciado": "O delegado pode conceder fiança nos crimes cuja pena máxima não passe de:", "opcoes": ["4 anos", "2 anos", "8 anos", "6 anos"], "explicacao": "Art. 322 do CPP. Acima disso, só o juiz."}, {"id": 10792, "materia": "ppen", "nivel": 4, "enunciado": "Para investigar uma ameaça, crime punido com detenção, o delegado pediu a interceptação do celular do suspeito. O juiz deve:", "opcoes": ["Negar o pedido", "Autorizar por 15 dias", "Autorizar por 30 dias", "Autorizar se a vítima pedir"], "explicacao": "Art. 2º, III, da Lei 9.296/1996: a interceptação só cabe em crime punido com reclusão."}, {"id": 10793, "materia": "ppen", "nivel": 4, "enunciado": "O juiz autorizou a interceptação do telefone de um suspeito. O prazo inicial é de:", "opcoes": ["15 dias, renováveis", "30 dias, sem renovação", "60 dias, renováveis", "5 dias, sem renovação"], "explicacao": "Art. 5º da Lei 9.296/1996: 15 dias, renováveis por igual tempo se indispensável."}, {"id": 10794, "materia": "ppen", "nivel": 3, "enunciado": "Num homicídio, o corpo sumiu, mas os vestígios ainda existem. A confissão do acusado:", "opcoes": ["Não supre o exame de corpo de delito", "Substitui o exame de corpo de delito", "Supre o exame se for gravada", "Supre o exame se o MP aceitar"], "explicacao": "Art. 158 do CPP: a confissão não pode suprir o exame quando há vestígios."}, {"id": 10795, "materia": "ppen", "nivel": 0, "enunciado": "Um vendedor viu um assaltante fugindo e o segurou até a polícia chegar. Pelo CPP:", "opcoes": ["Qualquer pessoa pode prender em flagrante", "Só policiais podem prender alguém em flagrante", "Só o delegado pode prender em flagrante", "Só se prende com mandado judicial"], "explicacao": "Art. 301 do CPP: qualquer do povo pode e a polícia deve prender em flagrante."}, {"id": 10796, "materia": "ppen", "nivel": 2, "enunciado": "No inquérito, o advogado de Téo quis contestar cada depoimento, como num processo. Isso não é obrigatório porque o inquérito é:", "opcoes": ["Inquisitivo", "Contraditório", "Judicial", "Acusatório"], "explicacao": "No inquérito não há contraditório pleno."}, {"id": 10797, "materia": "const", "nivel": 0, "enunciado": "Cláudio foi preso e quer saber quem são os policiais que o prenderam. A Constituição garante a ele:", "opcoes": ["Identificação dos responsáveis", "Escolher o juiz que vai julgar o caso", "Cela individual com televisão", "Soltura em até uma hora"], "explicacao": "Art. 5º, LXIV: o preso tem direito à identificação dos responsáveis por sua prisão."}, {"id": 10798, "materia": "const", "nivel": 0, "enunciado": "Rosa quer opinar nas redes sobre a política da cidade. Pela Constituição, a manifestação do pensamento é:", "opcoes": ["Livre, vedado o anonimato", "Livre e sempre anônima", "Proibida sobre política", "Livre só com licença"], "explicacao": "Art. 5º, IV, da Constituição."}, {"id": 10799, "materia": "const", "nivel": 1, "enunciado": "Na Bahia, a apuração de infrações penais e a função de polícia judiciária cabem à:", "opcoes": ["Polícia Civil", "Polícia Militar", "Polícia Federal", "Guarda Municipal"], "explicacao": "Art. 144, § 4º, da Constituição."}, {"id": 10800, "materia": "const", "nivel": 0, "enunciado": "Numa festa de rua em Salvador, o patrulhamento ostensivo fica a cargo da:", "opcoes": ["Polícia Militar", "Polícia Civil", "Polícia Penal", "Polícia Rodoviária Federal"], "explicacao": "Art. 144, § 5º: polícia ostensiva e preservação da ordem pública."}, {"id": 10801, "materia": "const", "nivel": 1, "enunciado": "A segurança dos presídios estaduais da Bahia é atribuição da:", "opcoes": ["Polícia Penal", "Polícia Civil", "Guarda Municipal", "Polícia Militar"], "explicacao": "Art. 144, § 5º-A, incluído pela EC 104/2019."}, {"id": 10802, "materia": "const", "nivel": 0, "enunciado": "Teo está preso sem ordem judicial e sem flagrante. Para soltá-lo, usa-se o:", "opcoes": ["Habeas corpus", "Habeas data", "Mandado de injunção", "Ação popular"], "explicacao": "Art. 5º, LXVIII: protege a liberdade de locomoção."}, {"id": 10803, "materia": "const", "nivel": 3, "enunciado": "Um eleitor quer anular um contrato da prefeitura que dá prejuízo aos cofres públicos. Ele pode propor:", "opcoes": ["Ação popular", "Habeas data", "Mandado de injunção", "Habeas corpus"], "explicacao": "Art. 5º, LXXIII: qualquer cidadão pode propor ação popular contra ato lesivo ao patrimônio público."}, {"id": 10804, "materia": "const", "nivel": 2, "enunciado": "Iara foi presa em flagrante. A prisão deve ser comunicada imediatamente:", "opcoes": ["Ao juiz e à família ou a quem ela indicar", "Apenas ao delegado-geral do estado", "Ao governador e à imprensa local", "Ao Ministério Público, só no dia seguinte"], "explicacao": "Art. 5º, LXII, da Constituição."}, {"id": 10805, "materia": "const", "nivel": 1, "enunciado": "Gabriel, brasileiro nato, cometeu um crime na Espanha e fugiu para o Brasil. Ele pode ser extraditado?", "opcoes": ["Não, em nenhuma hipótese", "Sim, se a Espanha pedir", "Sim, se for tráfico de drogas", "Sim, se o STF autorizar"], "explicacao": "Art. 5º, LI: brasileiro nato nunca é extraditado."}, {"id": 10806, "materia": "const", "nivel": 4, "enunciado": "Pablo é brasileiro naturalizado há 10 anos e foi acusado de tráfico de drogas na Bolívia. Ele:", "opcoes": ["Pode ser extraditado, se comprovado o envolvimento", "Nunca pode ser extraditado, por ser brasileiro", "Só pode ser extraditado se o crime for anterior à naturalização", "Só pode ser extraditado por crime político"], "explicacao": "Art. 5º, LI: o naturalizado pode ser extraditado por crime comum anterior à naturalização ou por tráfico de drogas, a qualquer tempo."}, {"id": 10807, "materia": "const", "nivel": 2, "enunciado": "Zeca foi preso por praticar racismo. Pela Constituição, esse crime é:", "opcoes": ["Inafiançável e imprescritível", "Afiançável e prescritível", "Inafiançável, mas prescritível", "Afiançável, mas imprescritível"], "explicacao": "Art. 5º, XLII, da Constituição."}, {"id": 10808, "materia": "const", "nivel": 3, "enunciado": "Um grupo armado tentou ocupar a sede do governo para derrubar a ordem constitucional. Pela Constituição, esse crime é:", "opcoes": ["Inafiançável e imprescritível", "Afiançável e prescritível", "Inafiançável, mas prescritível", "Hediondo, mas afiançável"], "explicacao": "Art. 5º, XLIV, da Constituição."}, {"id": 10809, "materia": "const", "nivel": 4, "enunciado": "Durante uma guerra declarada, um militar brasileiro foi condenado por traição. Nesse caso, a pena de morte:", "opcoes": ["É admitida", "É proibida", "Vale só para civis", "Depende de plebiscito"], "explicacao": "Art. 5º, XLVII, \"a\": a única exceção à proibição é a guerra declarada."}, {"id": 10810, "materia": "const", "nivel": 0, "enunciado": "Jonas foi denunciado por furto, mas ainda não foi condenado de forma definitiva. Até lá, ele é considerado:", "opcoes": ["Inocente", "Culpado", "Condenado provisório", "Culpado presumido"], "explicacao": "Art. 5º, LVII: presunção de inocência até o trânsito em julgado."}, {"id": 10811, "materia": "const", "nivel": 1, "enunciado": "No interrogatório, um suspeito confessou após ser torturado. Essa prova é:", "opcoes": ["Inadmissível", "Válida, se for verdade", "Válida, com aval do juiz", "Válida só no inquérito"], "explicacao": "Art. 5º, LVI: são inadmissíveis as provas obtidas por meios ilícitos."}, {"id": 10812, "materia": "const", "nivel": 1, "enunciado": "O governador da Bahia é eleito para um mandato de:", "opcoes": ["4 anos, com uma reeleição", "5 anos, sem reeleição", "4 anos, sem reeleição", "6 anos, com uma reeleição"], "explicacao": "Art. 28 e art. 14, § 5º, da Constituição."}, {"id": 10813, "materia": "const", "nivel": 4, "enunciado": "Um deputado estadual quer criar um novo crime numa lei da Bahia. Isso não é possível porque legislar sobre direito penal é competência:", "opcoes": ["Privativa da União", "Comum dos entes", "Concorrente dos estados", "Exclusiva dos municípios"], "explicacao": "Art. 22, I, da Constituição."}, {"id": 10814, "materia": "const", "nivel": 3, "enunciado": "O Presidente da República foi acusado de crime comum e a Câmara autorizou o processo. Ele será julgado pelo:", "opcoes": ["STF", "STJ", "Senado", "TSE"], "explicacao": "Art. 102, I, \"b\", e art. 86. Nos crimes de responsabilidade, julga o Senado."}, {"id": 10815, "materia": "const", "nivel": 0, "enunciado": "Um guarda exigiu que Kiko vestisse terno para entrar numa praça pública, sem lei nenhuma prevendo isso. Isso fere o princípio da:", "opcoes": ["Legalidade", "Publicidade", "Eficiência", "Anterioridade"], "explicacao": "Art. 5º, II: ninguém é obrigado a fazer ou deixar de fazer algo senão em virtude de lei."}, {"id": 10816, "materia": "const", "nivel": 3, "enunciado": "Sem o consentimento do morador, durante o dia, a polícia pode entrar na casa de Ugo:", "opcoes": ["Com ordem judicial, em flagrante, desastre ou socorro", "Só com ordem judicial, nunca em caso de flagrante", "Sempre que houver denúncia anônima de crime dentro da casa", "Só com autorização por escrito do delegado"], "explicacao": "Art. 5º, XI, da Constituição."}, {"id": 10817, "materia": "adm", "nivel": 1, "enunciado": "Um delegado nomeou o próprio filho para um cargo em comissão subordinado a ele. Isso é:", "opcoes": ["Nepotismo, proibido", "Permitido, por ser confiança", "Permitido, se ele for formado", "Só uma falta de ética"], "explicacao": "A Súmula Vinculante 13 proíbe o nepotismo."}, {"id": 10818, "materia": "adm", "nivel": 2, "enunciado": "Um chefe de polícia pôs o próprio nome e foto numa campanha oficial do órgão. Isso fere o princípio da:", "opcoes": ["Impessoalidade", "Eficiência", "Legalidade", "Continuidade"], "explicacao": "Art. 37, § 1º: a publicidade oficial não pode promover autoridades."}, {"id": 10819, "materia": "adm", "nivel": 1, "enunciado": "A prefeitura demoliu uma obra irregular que ameaçava cair, sem precisar de ordem judicial. Isso mostra o atributo da:", "opcoes": ["Autoexecutoriedade", "Presunção de legitimidade", "Tipicidade", "Imperatividade"], "explicacao": "A Administração executa certos atos por seus próprios meios."}, {"id": 10820, "materia": "adm", "nivel": 0, "enunciado": "O agente aplicou uma multa a Beto. Até Beto provar o contrário, a multa é considerada verdadeira e legal, pela:", "opcoes": ["Presunção de legitimidade", "Autoexecutoriedade", "Discricionariedade", "Hierarquia"], "explicacao": "Os atos administrativos se presumem legítimos e verdadeiros até prova em contrário."}, {"id": 10821, "materia": "adm", "nivel": 1, "enunciado": "O poder que permite punir o servidor que faltou ao serviço sem justificativa é o:", "opcoes": ["Disciplinar", "De polícia", "Regulamentar", "Normativo"], "explicacao": "O poder disciplinar apura e pune infrações dos servidores."}, {"id": 10822, "materia": "adm", "nivel": 0, "enunciado": "A vigilância sanitária interditou um restaurante sujo. Isso é exercício do poder:", "opcoes": ["De polícia", "Disciplinar", "Hierárquico", "Regulamentar"], "explicacao": "O poder de polícia limita atividades particulares em favor do interesse público."}, {"id": 10823, "materia": "adm", "nivel": 3, "enunciado": "A Administração revogou uma autorização que deixou de ser conveniente. A revogação:", "opcoes": ["Tem efeito para o futuro", "Tem efeito retroativo", "Só o Judiciário pode fazer", "Desfaz os efeitos passados"], "explicacao": "A revogação atinge atos válidos por mérito e tem efeitos ex nunc."}, {"id": 10824, "materia": "adm", "nivel": 3, "enunciado": "A Administração descobriu que um ato seu era ilegal. Ela deve:", "opcoes": ["Anulá-lo, com efeito retroativo", "Revogá-lo, com efeito futuro", "Aguardar decisão do Judiciário", "Mantê-lo, por segurança jurídica"], "explicacao": "Súmula 473 do STF: a Administração anula seus atos ilegais."}, {"id": 10825, "materia": "adm", "nivel": 4, "enunciado": "Na Lei 9.784/1999, o direito de a Administração anular ato ilegal que favoreceu alguém de boa-fé decai em:", "opcoes": ["5 anos", "2 anos", "10 anos", "1 ano"], "explicacao": "Art. 54 da Lei 9.784/1999."}, {"id": 10826, "materia": "adm", "nivel": 2, "enunciado": "Um servidor usou o carro oficial para levar a família à praia no fim de semana. Isso pode configurar:", "opcoes": ["Improbidade administrativa", "Exercício regular do cargo", "Poder discricionário", "Mérito administrativo"], "explicacao": "Usar bens públicos em proveito particular está entre os atos de improbidade (Lei 8.429/1992, art. 9º)."}, {"id": 10827, "materia": "adm", "nivel": 2, "enunciado": "Um ato foi assinado por um servidor que não tinha atribuição legal para isso. O vício está no elemento:", "opcoes": ["Competência", "Forma", "Objeto", "Motivo"], "explicacao": "A competência é o elemento ligado a quem pode praticar o ato."}, {"id": 10828, "materia": "adm", "nivel": 3, "enunciado": "O chefe removeu um investigador para outra cidade só para puni-lo por uma briga pessoal. Houve desvio de:", "opcoes": ["Finalidade", "Competência", "Forma", "Objeto"], "explicacao": "A remoção não serve para punir; usá-la assim é desvio de finalidade."}, {"id": 10829, "materia": "adm", "nivel": 4, "enunciado": "Uma viatura em serviço bateu num carro particular. A responsabilidade do Estado pelo dano é, em regra:", "opcoes": ["Objetiva, com regresso contra o agente", "Subjetiva, provando-se a culpa do Estado", "Só do agente, que paga com seus bens", "Inexistente, por ser serviço público"], "explicacao": "Art. 37, § 6º, da Constituição: o Estado responde e pode cobrar do agente que agiu com dolo ou culpa."}, {"id": 10830, "materia": "adm", "nivel": 0, "enunciado": "Na delegacia, atender o cidadão rápido, com qualidade e sem desperdício atende ao princípio da:", "opcoes": ["Eficiência", "Legalidade", "Publicidade", "Moralidade"], "explicacao": "A eficiência foi incluída no art. 37 pela EC 19/1998."}, {"id": 10831, "materia": "adm", "nivel": 1, "enunciado": "Os cargos em comissão destinam-se apenas às funções de:", "opcoes": ["Direção, chefia e assessoramento", "Rotina técnica e operacional", "Policiamento e fiscalização", "Atendimento ao público em geral"], "explicacao": "Art. 37, V, da Constituição."}, {"id": 10832, "materia": "adm", "nivel": 2, "enunciado": "Aprovada no concurso, Clara será estável depois de:", "opcoes": ["3 anos e avaliação de desempenho", "2 anos e aprovação em prova de títulos", "1 ano e estágio probatório", "5 anos e curso de formação"], "explicacao": "Art. 41 da Constituição."}, {"id": 10833, "materia": "adm", "nivel": 4, "enunciado": "O servidor estável só perde o cargo por sentença transitada em julgado, processo administrativo com ampla defesa ou:", "opcoes": ["Avaliação periódica de desempenho", "Decisão fundamentada do chefe imediato", "Mudança de governo", "Ausência de vagas no órgão"], "explicacao": "Art. 41, § 1º, da Constituição (há ainda o excesso de despesa, art. 169)."}, {"id": 10834, "materia": "adm", "nivel": 3, "enunciado": "A Secretaria de Segurança vai comprar coletes comuns no mercado. Pela Lei 14.133/2021, a modalidade adequada é o:", "opcoes": ["Pregão", "Concurso", "Leilão", "Diálogo competitivo"], "explicacao": "O pregão é a modalidade para bens e serviços comuns."}, {"id": 10835, "materia": "leg", "nivel": 0, "enunciado": "Lívia foi agredida pelo marido dentro de casa. A lei que trata especialmente desse caso é a:", "opcoes": ["Lei Maria da Penha", "Lei Seca", "Lei de Drogas", "Lei de Execução Penal"], "explicacao": "Lei 11.340/2006: violência doméstica e familiar contra a mulher."}, {"id": 10836, "materia": "leg", "nivel": 1, "enunciado": "Lívia pediu medidas protetivas na delegacia. O juiz deve decidir o pedido em até:", "opcoes": ["48 horas", "10 dias", "30 dias", "5 dias"], "explicacao": "Art. 18 da Lei 11.340/2006."}, {"id": 10837, "materia": "leg", "nivel": 2, "enunciado": "O marido de Lívia se aproximou dela, desrespeitando a medida protetiva. Isso é:", "opcoes": ["Crime da própria Lei Maria da Penha", "Só infração administrativa, sem pena", "Contravenção penal", "Fato atípico"], "explicacao": "Art. 24-A da Lei 11.340/2006."}, {"id": 10838, "materia": "leg", "nivel": 3, "enunciado": "Joel ameaçou a ex-companheira e o advogado pediu transação penal, da Lei 9.099/1995. O pedido:", "opcoes": ["Não cabe nesse caso", "Cabe sempre", "Cabe se ela aceitar", "Cabe se ele for primário"], "explicacao": "Art. 41 da Lei 11.340/2006 e Súmula 536 do STJ."}, {"id": 10839, "materia": "leg", "nivel": 4, "enunciado": "Nilo deu um tapa na esposa e causou lesão leve. Ela disse que não quer processá-lo. A ação penal:", "opcoes": ["Segue mesmo assim", "É arquivada", "Passa a ser privada", "É extinta pela renúncia"], "explicacao": "Súmula 542 do STJ: lesão corporal em violência doméstica contra a mulher é de ação pública incondicionada."}, {"id": 10840, "materia": "leg", "nivel": 1, "enunciado": "Pela Lei de Drogas, quem é pego com droga só para consumo próprio NÃO está sujeito a:", "opcoes": ["Pena de prisão", "Advertência", "Prestação de serviços", "Medida educativa"], "explicacao": "O art. 28 da Lei 11.343/2006 não prevê prisão para o usuário."}, {"id": 10841, "materia": "leg", "nivel": 2, "enunciado": "Rogério vendia cocaína na porta de uma escola. Pela Lei de Drogas, isso:", "opcoes": ["Aumenta a pena de 1/6 a 2/3", "Diminui a pena de 1/3", "Não altera a pena", "Dobra a pena sempre"], "explicacao": "Art. 40, III, da Lei 11.343/2006."}, {"id": 10842, "materia": "leg", "nivel": 3, "enunciado": "O tráfico privilegiado (art. 33, § 4º) exige que o agente seja primário, tenha bons antecedentes e:", "opcoes": ["Não se dedique a crimes nem integre organização", "Tenha sido flagrado com pouca quantidade de droga", "Seja usuário e venda para sustentar o vício", "Confesse o crime ainda no inquérito"], "explicacao": "Art. 33, § 4º, da Lei 11.343/2006: a pena cai de 1/6 a 2/3."}, {"id": 10843, "materia": "leg", "nivel": 4, "enunciado": "Segundo o STF e o Pacote Anticrime, o tráfico privilegiado:", "opcoes": ["Não é crime hediondo", "É crime hediondo", "É equiparado a hediondo", "É contravenção penal"], "explicacao": "STF, HC 118.533 e art. 112, § 5º, da LEP."}, {"id": 10844, "materia": "leg", "nivel": 0, "enunciado": "Saulo andava pela rua com um revólver de uso permitido na cintura, sem autorização. O crime é:", "opcoes": ["Porte ilegal", "Posse irregular", "Disparo de arma", "Comércio ilegal"], "explicacao": "Art. 14 da Lei 10.826/2003."}, {"id": 10845, "materia": "leg", "nivel": 2, "enunciado": "Lúcio guardava no armário de casa uma pistola de uso permitido sem registro. O crime é:", "opcoes": ["Posse irregular", "Porte ilegal", "Omissão de cautela", "Comércio ilegal"], "explicacao": "Art. 12 da Lei 10.826/2003: manter a arma dentro da residência."}, {"id": 10846, "materia": "leg", "nivel": 4, "enunciado": "Ao apreender uma arma, a polícia viu que o número de série tinha sido raspado. Esse crime está no artigo que trata de arma de uso:", "opcoes": ["Restrito (art. 16)", "Permitido (art. 14)", "Permitido (art. 12)", "Civil (art. 13)"], "explicacao": "Art. 16, § 1º, IV, da Lei 10.826/2003."}, {"id": 10847, "materia": "leg", "nivel": 4, "enunciado": "Raí deixou a arma carregada sobre a mesa e o filho de 10 anos a pegou. Raí cometeu:", "opcoes": ["Omissão de cautela", "Porte ilegal", "Posse irregular", "Disparo de arma"], "explicacao": "Art. 13 da Lei 10.826/2003."}, {"id": 10848, "materia": "leg", "nivel": 1, "enunciado": "Davi, de 11 anos, pichou o muro da escola. Pelo ECA, ele:", "opcoes": ["Recebe medida de proteção", "Recebe internação", "Responde pelo Código Penal", "Recebe medida socioeducativa"], "explicacao": "Art. 105 do ECA: ao ato infracional de criança cabem medidas de proteção."}, {"id": 10849, "materia": "leg", "nivel": 3, "enunciado": "A internação de adolescente que cometeu ato infracional não pode passar de:", "opcoes": ["3 anos", "1 ano", "5 anos", "10 anos"], "explicacao": "Art. 121, § 3º, do ECA."}, {"id": 10850, "materia": "leg", "nivel": 4, "enunciado": "Bento, de 19 anos, chamou um adolescente para furtarem juntos. Além do furto, Bento responde por:", "opcoes": ["Corrupção de menores", "Associação criminosa", "Favorecimento pessoal", "Nenhum outro crime"], "explicacao": "Art. 244-B do ECA. A Súmula 500 do STJ diz que o crime é formal."}, {"id": 10851, "materia": "leg", "nivel": 1, "enunciado": "Um policial algemou um preso calmo e o expôs à imprensa só para humilhá-lo. Isso pode configurar:", "opcoes": ["Abuso de autoridade", "Exercício regular de direito", "Estrito cumprimento do dever", "Prevaricação"], "explicacao": "Lei 13.869/2019, art. 13."}, {"id": 10852, "materia": "leg", "nivel": 4, "enunciado": "Na Lei de Abuso de Autoridade, o crime só existe se o agente quis prejudicar alguém, beneficiar-se ou:", "opcoes": ["Agir por capricho ou satisfação pessoal", "Cumprir ordem expressa e escrita do superior", "Interpretar a lei de forma diferente", "Agir com culpa, por descuido"], "explicacao": "Art. 1º, §§ 1º e 2º, da Lei 13.869/2019."}, {"id": 10853, "materia": "leg", "nivel": 2, "enunciado": "Policiais espancaram um suspeito para que ele confessasse um roubo. O crime é:", "opcoes": ["Tortura", "Lesão corporal leve", "Constrangimento ilegal", "Exercício arbitrário"], "explicacao": "Art. 1º, I, \"a\", da Lei 9.455/1997."}, {"id": 10854, "materia": "leg", "nivel": 3, "enunciado": "O policial condenado por tortura perde o cargo:", "opcoes": ["Automaticamente", "Só se o juiz fundamentar", "Só após processo administrativo", "Nunca, por ser estável"], "explicacao": "Art. 1º, § 5º, da Lei 9.455/1997: efeito automático da condenação."}, {"id": 10855, "materia": "leg", "nivel": 0, "enunciado": "Dirigir com a capacidade alterada por álcool é crime previsto no:", "opcoes": ["Código de Trânsito Brasileiro", "Código Civil", "Estatuto da Criança", "Código do Consumidor"], "explicacao": "Art. 306 do CTB."}, {"id": 10856, "materia": "leg", "nivel": 1, "enunciado": "Parado numa blitz, Juan se recusou a fazer o teste do bafômetro. Pelo CTB, isso gera:", "opcoes": ["Infração gravíssima", "Prisão em flagrante", "Nenhuma consequência", "Só uma advertência"], "explicacao": "Art. 165-A do CTB: multa e suspensão do direito de dirigir."}, {"id": 10857, "materia": "leg", "nivel": 4, "enunciado": "Embriagado, Leandro atropelou e matou um ciclista sem querer. A pena do homicídio culposo nesse caso é de:", "opcoes": ["Reclusão de 5 a 8 anos", "Detenção de 2 a 4 anos", "Reclusão de 12 a 30 anos", "Detenção de 6 meses a 1 ano"], "explicacao": "Art. 302, § 3º, do CTB."}, {"id": 10858, "materia": "leg", "nivel": 2, "enunciado": "Humilhar uma pessoa idosa por causa da idade dela é crime previsto no:", "opcoes": ["Estatuto da Pessoa Idosa", "Estatuto da Criança", "Código de Trânsito", "Estatuto do Desarmamento"], "explicacao": "Art. 96, § 1º, da Lei 10.741/2003."}, {"id": 10859, "materia": "leg", "nivel": 4, "enunciado": "Cinco pessoas se organizaram, com tarefas divididas, para explodir caixas eletrônicos e levar o dinheiro. Pela Lei 12.850/2013, elas formam:", "opcoes": ["Organização criminosa", "Associação eventual", "Concurso de pessoas", "Milícia particular"], "explicacao": "Quatro ou mais pessoas, estrutura e divisão de tarefas, para crimes com pena máxima acima de 4 anos."}, {"id": 10860, "materia": "leg", "nivel": 1, "enunciado": "Nestor matou o vizinho por causa de um latido de cachorro, por motivo fútil. Esse crime é:", "opcoes": ["Hediondo", "Contravenção", "De menor potencial ofensivo", "Culposo"], "explicacao": "O homicídio qualificado é hediondo (art. 1º, I, da Lei 8.072/1990)."}, {"id": 10861, "materia": "port", "nivel": 0, "enunciado": "Complete: \"O perito fez uma ____ completa no local do crime.\"", "opcoes": ["inspeção", "inspessão", "inspecção", "inspesão"], "explicacao": "A grafia correta é \"inspeção\"."}, {"id": 10862, "materia": "port", "nivel": 0, "enunciado": "Em \"A viatura chegou rápido ao local\", o sujeito é:", "opcoes": ["A viatura", "Chegou", "Rápido", "Ao local"], "explicacao": "Quem chegou? A viatura."}, {"id": 10863, "materia": "port", "nivel": 2, "enunciado": "Complete o relatório: \"Os ____ chegaram cedo ao cartório.\"", "opcoes": ["escrivães", "escrivãos", "escrivões", "escrivãoes"], "explicacao": "Escrivão faz o plural em -ães."}, {"id": 10864, "materia": "port", "nivel": 1, "enunciado": "Complete: \"Os agentes ____ a ocorrência ontem à noite.\"", "opcoes": ["registraram", "registrarão", "registrou", "registrara-se"], "explicacao": "\"Ontem\" pede o pretérito, e o sujeito plural pede \"registraram\"."}, {"id": 10865, "materia": "port", "nivel": 2, "enunciado": "Assinale a frase com o acento grave (crase) correto:", "opcoes": ["O delegado foi à delegacia.", "Ele começou à investigar.", "Entreguei o laudo à ele.", "Chegamos à pé ao local."], "explicacao": "Não há crase antes de verbo, de pronome pessoal nem de palavra masculina."}, {"id": 10866, "materia": "port", "nivel": 2, "enunciado": "Em \"O investigador, porém, não desistiu do caso\", a palavra \"porém\" indica:", "opcoes": ["Oposição", "Causa", "Conclusão", "Tempo"], "explicacao": "\"Porém\" é conjunção adversativa."}, {"id": 10867, "materia": "port", "nivel": 3, "enunciado": "Assinale a frase do relatório com a concordância correta:", "opcoes": ["Houve muitas denúncias na semana.", "Houveram muitas denúncias na semana.", "Existe vários suspeitos no caso.", "Fazem três dias que ele sumiu."], "explicacao": "\"Haver\" (existir) e \"fazer\" (tempo) são impessoais; \"existir\" concorda com o sujeito."}, {"id": 10868, "materia": "port", "nivel": 3, "enunciado": "Em \"Roubaram a viatura da delegacia\", o sujeito é:", "opcoes": ["Indeterminado", "Oculto", "Simples", "Inexistente"], "explicacao": "Verbo na 3ª pessoa do plural sem indicar quem fez: sujeito indeterminado."}, {"id": 10869, "materia": "port", "nivel": 4, "enunciado": "Na norma-padrão, assinale a regência correta:", "opcoes": ["O agente assistiu ao vídeo da câmera.", "O agente assistiu o vídeo da câmera ontem.", "O soldado obedeceu o regulamento.", "Ele aspira o cargo de delegado."], "explicacao": "Assistir (ver), obedecer e aspirar (desejar) pedem a preposição \"a\"."}, {"id": 10870, "materia": "port", "nivel": 0, "enunciado": "O antônimo de \"culpado\", no julgamento, é:", "opcoes": ["inocente", "réu", "suspeito", "condenado"], "explicacao": "Antônimo é a palavra de sentido contrário."}, {"id": 10871, "materia": "port", "nivel": 0, "enunciado": "Complete com a proparoxítona: \"O ____ legista assinou o laudo.\"", "opcoes": ["médico", "perito", "doutor", "agente"], "explicacao": "Mé-di-co: acento na antepenúltima sílaba."}, {"id": 10872, "materia": "port", "nivel": 2, "enunciado": "Em \"O suspeito fugiu porque viu a viatura\", a oração \"porque viu a viatura\" indica:", "opcoes": ["Causa", "Consequência", "Finalidade", "Concessão"], "explicacao": "\"Porque\" introduz o motivo da fuga."}, {"id": 10873, "materia": "port", "nivel": 3, "enunciado": "Assinale o uso correto de \"mas\" ou \"mais\":", "opcoes": ["Correu muito, mas não alcançou o ladrão.", "Correu muito, mais não alcançou o ladrão.", "O cabo é mas rápido que o sargento.", "Precisamos de mas provas no inquérito."], "explicacao": "\"Mas\" indica oposição; \"mais\" indica quantidade ou intensidade."}, {"id": 10874, "materia": "port", "nivel": 3, "enunciado": "Em \"Embora chovesse, a operação aconteceu\", a palavra \"embora\" introduz ideia de:", "opcoes": ["Concessão", "Causa", "Condição", "Conformidade"], "explicacao": "Conjunção concessiva: o fato contrário não impede a ação."}, {"id": 10875, "materia": "port", "nivel": 4, "enunciado": "No relatório, assinale a colocação pronominal correta pela norma-padrão:", "opcoes": ["Ninguém me avisou da operação.", "Ninguém avisou-me da operação.", "Jamais entregaram-me o laudo.", "Nunca deram-me o mandado."], "explicacao": "Palavras negativas atraem o pronome para antes do verbo (próclise)."}, {"id": 10876, "materia": "port", "nivel": 2, "enunciado": "Complete: \"O delegado não abriu nenhuma ____ para o caso.\"", "opcoes": ["exceção", "excessão", "esceção", "exseção"], "explicacao": "A grafia correta é \"exceção\"."}, {"id": 10877, "materia": "port", "nivel": 1, "enunciado": "Em \"Os peritos analisaram as provas\", o objeto direto é:", "opcoes": ["as provas", "os peritos", "analisaram", "peritos analisaram"], "explicacao": "Analisaram o quê? As provas."}, {"id": 10878, "materia": "port", "nivel": 4, "enunciado": "Na norma-padrão, \"onde\" está corretamente usado em:", "opcoes": ["A rua onde ocorreu o crime foi isolada.", "Na época onde aconteceu o crime, chovia.", "Foi um caso onde todos se enganaram.", "No momento onde ele chegou, saímos."], "explicacao": "\"Onde\" só deve se referir a lugar físico."}, {"id": 10879, "materia": "dh", "nivel": 0, "enunciado": "Maria é acusada de um crime grave. Mesmo assim, ela tem o direito de não ser torturada, porque os direitos humanos:", "opcoes": ["Valem para todas as pessoas", "Valem só para quem é inocente", "Valem só para brasileiros", "Dependem do crime cometido"], "explicacao": "Os direitos humanos são universais."}, {"id": 10880, "materia": "dh", "nivel": 2, "enunciado": "Um país alegou que, por sua cultura, pode negar direitos humanos a certo grupo. Isso contraria a característica da:", "opcoes": ["Universalidade", "Temporariedade", "Disponibilidade", "Territorialidade"], "explicacao": "Os direitos humanos valem para todas as pessoas, em qualquer lugar."}, {"id": 10881, "materia": "dh", "nivel": 2, "enunciado": "O Pacto de San José da Costa Rica proíbe a prisão por dívida, com uma exceção. Ela vale para o devedor de:", "opcoes": ["Pensão alimentícia", "Aluguel atrasado", "Impostos federais", "Contrato bancário"], "explicacao": "Art. 7º, item 7, da Convenção Americana."}, {"id": 10882, "materia": "dh", "nivel": 4, "enunciado": "Zico era depositário de bens penhorados e sumiu com eles. O juiz pode decretar a prisão civil dele?", "opcoes": ["Não, é proibida", "Sim, por até 1 ano", "Sim, por até 3 meses", "Sim, se o credor pedir"], "explicacao": "Súmula Vinculante 25 do STF."}, {"id": 10883, "materia": "dh", "nivel": 2, "enunciado": "Para a Convenção da ONU sobre os Direitos da Criança, criança é toda pessoa com menos de:", "opcoes": ["18 anos", "12 anos", "14 anos", "16 anos"], "explicacao": "Art. 1º da Convenção (1989)."}, {"id": 10884, "materia": "dh", "nivel": 4, "enunciado": "Uma família quer denunciar o Brasil por violação de direitos humanos no sistema interamericano. A petição vai primeiro para a:", "opcoes": ["Comissão Interamericana", "Corte Interamericana", "Assembleia da ONU", "Corte de Haia"], "explicacao": "Só a Comissão e os Estados podem levar um caso à Corte (art. 61 da Convenção Americana)."}, {"id": 10885, "materia": "dh", "nivel": 2, "enunciado": "O diretor de um presídio quer seguir as regras mínimas da ONU para o tratamento dos presos. Ele deve consultar as:", "opcoes": ["Regras de Mandela", "Diretrizes de Riad", "Regras de Pequim", "Normas de Kyoto"], "explicacao": "As Diretrizes de Riad e as Regras de Pequim tratam de jovens."}, {"id": 10886, "materia": "dh", "nivel": 4, "enunciado": "O Brasil aprovou um tratado de direitos humanos por maioria simples, sem o rito de emenda. Diante das leis comuns, ele fica:", "opcoes": ["Acima delas", "Abaixo delas", "No mesmo nível", "Acima da Constituição"], "explicacao": "Para o STF (RE 466.343), tem status supralegal: abaixo da Constituição e acima das leis."}, {"id": 10887, "materia": "dh", "nivel": 0, "enunciado": "Na cadeia, o preso tem direito ao respeito à sua:", "opcoes": ["Integridade física e moral", "Liberdade de sair à noite", "Escolha da cela e do colega", "Dispensa de qualquer regra"], "explicacao": "Art. 5º, XLIX, da Constituição."}, {"id": 10888, "materia": "dh", "nivel": 4, "enunciado": "A Convenção de Belém do Pará, da OEA, define violência contra a mulher como ação baseada no gênero que cause:", "opcoes": ["Morte, dano ou sofrimento físico, sexual ou psicológico", "Apenas lesão física comprovada por exame pericial no IML", "Somente dano patrimonial dentro do casamento", "Somente ofensa praticada em local público"], "explicacao": "Art. 1º da Convenção (1994)."}, {"id": 10889, "materia": "inf", "nivel": 0, "enunciado": "Ana recebeu um e-mail do \"banco\" com um link pedindo a senha dela. Isso é tentativa de:", "opcoes": ["Phishing", "Backup", "Firewall", "Download"], "explicacao": "Phishing é a fraude que imita instituições para roubar dados."}, {"id": 10890, "materia": "inf", "nivel": 0, "enunciado": "O HD do computador do cartório queimou, mas nenhum arquivo foi perdido, porque havia:", "opcoes": ["Backup", "Firewall", "Phishing", "Spam"], "explicacao": "Backup é a cópia de segurança dos dados."}, {"id": 10891, "materia": "inf", "nivel": 1, "enunciado": "O recurso que filtra e bloqueia conexões não autorizadas na rede é o:", "opcoes": ["Firewall", "Navegador", "Editor de texto", "Spam"], "explicacao": "O firewall controla o tráfego que entra e sai da rede."}, {"id": 10892, "materia": "inf", "nivel": 1, "enunciado": "No endereço de e-mail investigacao@pc.ba.gov.br, a parte que vem depois do @ é:", "opcoes": ["O domínio", "O usuário", "A senha", "O assunto"], "explicacao": "Antes do @ vem o usuário; depois, o domínio."}, {"id": 10893, "materia": "inf", "nivel": 2, "enunciado": "O escrivão quer mandar um e-mail a várias pessoas sem que uma veja o endereço das outras. Ele usa o campo:", "opcoes": ["Cco", "Cc", "Para", "Assunto"], "explicacao": "Cco é a cópia carbono oculta."}, {"id": 10894, "materia": "inf", "nivel": 2, "enunciado": "Um programa que parece útil, mas abre uma porta para o invasor, é chamado de:", "opcoes": ["Cavalo de Troia", "Worm", "Firewall", "Cookie"], "explicacao": "O cavalo de Troia (trojan) se disfarça de programa legítimo."}, {"id": 10895, "materia": "inf", "nivel": 3, "enunciado": "Um vírus infectou um computador da delegacia e, sozinho, passou para os outros da rede sem que ninguém abrisse nada. É um:", "opcoes": ["Worm", "Trojan", "Spyware", "Adware"], "explicacao": "O worm se replica e se propaga por conta própria."}, {"id": 10896, "materia": "inf", "nivel": 1, "enunciado": "No Excel, as células A1, A2 e A3 têm 2, 4 e 6. A fórmula =SOMA(A1:A3) retorna:", "opcoes": ["12", "6", "3", "246"], "explicacao": "2 + 4 + 6 = 12."}, {"id": 10897, "materia": "inf", "nivel": 3, "enunciado": "No Excel, B1 a B4 têm 10, 20, 30 e 40. A fórmula =MÉDIA(B1:B4) retorna:", "opcoes": ["25", "100", "40", "4"], "explicacao": "100 ÷ 4 = 25."}, {"id": 10898, "materia": "inf", "nivel": 3, "enunciado": "Uma VPN cria uma conexão:", "opcoes": ["Criptografada por uma rede pública", "Pública, sem nenhuma senha ou proteção", "Exclusiva para jogos online", "Que substitui o antivírus"], "explicacao": "A VPN cria um túnel protegido sobre a internet."}, {"id": 10899, "materia": "inf", "nivel": 4, "enunciado": "No Excel, com A1 = 7, a fórmula =SE(A1>=7;\"Aprovado\";\"Reprovado\") retorna:", "opcoes": ["Aprovado", "Reprovado", "#VALOR!", "7"], "explicacao": "7 >= 7 é verdadeiro, então retorna o primeiro valor."}, {"id": 10900, "materia": "inf", "nivel": 1, "enunciado": "Os pequenos arquivos que os sites gravam no navegador para lembrar preferências são os:", "opcoes": ["Cookies", "Vírus", "Drivers", "Macros"], "explicacao": "Cookies guardam dados de navegação e preferências."}, {"id": 10901, "materia": "rl", "nivel": 0, "enunciado": "Um investigador ouviu 3 testemunhas por dia durante 5 dias. Quantas ouviu ao todo?", "opcoes": ["15", "8", "12", "18"], "explicacao": "3 × 5 = 15."}, {"id": 10902, "materia": "rl", "nivel": 0, "enunciado": "Toda viatura da delegacia tem rádio. A viatura 12 é da delegacia. Logo:", "opcoes": ["A viatura 12 tem rádio", "A viatura 12 não tem rádio", "Só a viatura 12 tem rádio", "Nada se pode concluir"], "explicacao": "Se todas têm, a 12 também tem."}, {"id": 10903, "materia": "rl", "nivel": 1, "enunciado": "A negação de \"Todos os presos voltaram\" é:", "opcoes": ["Algum preso não voltou", "Nenhum preso voltou", "Todos os presos fugiram", "Algum preso voltou"], "explicacao": "Nega-se o \"todos\" com \"algum... não\"."}, {"id": 10904, "materia": "rl", "nivel": 1, "enunciado": "Numa fila, Léo é o 7º contando da frente e o 4º contando de trás. Quantas pessoas há na fila?", "opcoes": ["10", "11", "9", "12"], "explicacao": "7 + 4 − 1 = 10 (Léo foi contado duas vezes)."}, {"id": 10905, "materia": "rl", "nivel": 2, "enunciado": "A negação de \"O suspeito mentiu e fugiu\" é:", "opcoes": ["O suspeito não mentiu ou não fugiu", "O suspeito não mentiu e também não fugiu", "O suspeito mentiu ou fugiu", "O suspeito não mentiu, mas fugiu"], "explicacao": "Lei de De Morgan: ~(p ∧ q) = ~p ∨ ~q."}, {"id": 10906, "materia": "rl", "nivel": 2, "enunciado": "É verdade que \"Se chove, a ronda atrasa\". Hoje a ronda não atrasou. Logo:", "opcoes": ["Não choveu", "Choveu", "A ronda atrasou", "Nada se conclui"], "explicacao": "Modus tollens: se o consequente é falso, o antecedente também é."}, {"id": 10907, "materia": "rl", "nivel": 3, "enunciado": "Uma operação começou às 22h40 e durou 3h35. Ela terminou às:", "opcoes": ["2h15", "1h15", "2h05", "3h15"], "explicacao": "22h40 + 3h35 = 26h15, ou seja, 2h15 do dia seguinte."}, {"id": 10908, "materia": "rl", "nivel": 3, "enunciado": "Uma equipe faz ronda a cada 4 dias e outra a cada 6. Se saíram juntas hoje, voltarão a sair juntas daqui a:", "opcoes": ["12 dias", "24 dias", "10 dias", "6 dias"], "explicacao": "MMC de 4 e 6 = 12."}, {"id": 10909, "materia": "rl", "nivel": 4, "enunciado": "Quantas duplas diferentes de investigadores podem ser formadas com 5 investigadores?", "opcoes": ["10", "20", "25", "5"], "explicacao": "C(5,2) = 5 × 4 ÷ 2 = 10."}, {"id": 10910, "materia": "rl", "nivel": 4, "enunciado": "De quantas maneiras 4 agentes podem se organizar numa fila?", "opcoes": ["24", "16", "12", "4"], "explicacao": "4! = 4 × 3 × 2 × 1 = 24."}, {"id": 10911, "materia": "rl", "nivel": 2, "enunciado": "Uma frase equivalente a \"Se é policial militar, então é servidor\" é:", "opcoes": ["Se não é servidor, não é policial militar", "Se é servidor, então é policial militar", "Se não é policial militar, não é servidor", "É policial militar e não é servidor"], "explicacao": "Contrapositiva: p → q equivale a ~q → ~p."}, {"id": 10912, "materia": "rl", "nivel": 3, "enunciado": "Num grupo de 40 policiais, 25 falam inglês, 18 falam espanhol e 8 falam os dois. Quantos não falam nenhum?", "opcoes": ["5", "3", "8", "0"], "explicacao": "25 + 18 − 8 = 35 falam ao menos um; 40 − 35 = 5."}, {"id": 10913, "materia": "est", "nivel": 0, "enunciado": "Uma delegacia registrou 3, 5, 5, 7 e 10 ocorrências em 5 dias. A moda é:", "opcoes": ["5", "3", "7", "6"], "explicacao": "Moda é o valor que mais se repete."}, {"id": 10914, "materia": "est", "nivel": 1, "enunciado": "Com 3, 5, 5, 7 e 10 ocorrências em 5 dias, a média diária é:", "opcoes": ["6", "5", "7", "30"], "explicacao": "30 ÷ 5 = 6."}, {"id": 10915, "materia": "est", "nivel": 2, "enunciado": "A mediana dos tempos de resposta 12, 3, 9, 7 e 5 minutos é:", "opcoes": ["7", "9", "5", "12"], "explicacao": "Em ordem: 3, 5, 7, 9, 12. O valor do meio é 7."}, {"id": 10916, "materia": "est", "nivel": 2, "enunciado": "De 80 furtos registrados no mês, 20 foram de celular. O percentual de furtos de celular é:", "opcoes": ["25%", "20%", "40%", "80%"], "explicacao": "20 ÷ 80 = 0,25."}, {"id": 10917, "materia": "est", "nivel": 4, "enunciado": "A média de 4 provas de um candidato foi 7. Nas três primeiras ele tirou 6, 8 e 5. A quarta nota foi:", "opcoes": ["9", "7", "8", "10"], "explicacao": "Soma total = 28; 28 − 19 = 9."}, {"id": 10918, "materia": "est", "nivel": 3, "enunciado": "Se o desvio padrão de um conjunto de dados é zero, então:", "opcoes": ["Todos os valores são iguais", "A média é igual a zero", "Todos os valores são negativos", "A moda é igual a zero"], "explicacao": "Não há dispersão em torno da média."}, {"id": 10919, "materia": "cont", "nivel": 0, "enunciado": "Uma loja tem R$ 2 mil guardados no cofre. No balanço, esse valor fica no:", "opcoes": ["Ativo", "Passivo", "Patrimônio líquido", "Resultado"], "explicacao": "Dinheiro é um bem: ativo."}, {"id": 10920, "materia": "cont", "nivel": 1, "enunciado": "Uma dívida da empresa com fornecedores é classificada como:", "opcoes": ["Passivo", "Ativo", "Receita", "Patrimônio líquido"], "explicacao": "Obrigações com terceiros ficam no passivo."}, {"id": 10921, "materia": "cont", "nivel": 2, "enunciado": "Uma empresa tem ativo de R$ 500 mil e passivo de R$ 300 mil. O patrimônio líquido é:", "opcoes": ["R$ 200 mil", "R$ 800 mil", "R$ 300 mil", "R$ 500 mil"], "explicacao": "PL = Ativo − Passivo."}, {"id": 10922, "materia": "cont", "nivel": 3, "enunciado": "No método das partidas dobradas, a cada débito corresponde:", "opcoes": ["Um crédito de igual valor", "Outro débito de igual valor", "Um crédito com o dobro do valor", "Nenhum lançamento contrário"], "explicacao": "Não há débito sem crédito correspondente."}, {"id": 10923, "materia": "cont", "nivel": 3, "enunciado": "Ocorre passivo a descoberto quando:", "opcoes": ["O passivo supera o ativo", "O ativo supera o passivo", "O ativo é igual ao passivo", "O patrimônio líquido é positivo"], "explicacao": "O patrimônio líquido fica negativo."}, {"id": 10924, "materia": "cont", "nivel": 4, "enunciado": "A compra de mercadorias à vista, sem lucro ou prejuízo, é um fato contábil:", "opcoes": ["Permutativo", "Modificativo aumentativo", "Modificativo diminutivo", "Misto"], "explicacao": "Troca-se caixa por estoque: o patrimônio líquido não muda."}, {"id": 10925, "materia": "ml", "nivel": 0, "enunciado": "Uma faca de cozinha passou cortando a pele da vítima, sem perfurar. O instrumento agiu como:", "opcoes": ["Cortante", "Contundente", "Perfurante", "Térmico"], "explicacao": "Instrumento cortante age pelo gume, deslizando."}, {"id": 10926, "materia": "ml", "nivel": 1, "enunciado": "A vítima foi agredida com golpes de martelo. A lesão é produzida por instrumento:", "opcoes": ["Contundente", "Cortante", "Perfurante", "Perfurocortante"], "explicacao": "Martelo age por pressão ou choque: contundente."}, {"id": 10927, "materia": "ml", "nivel": 3, "enunciado": "Machado e facão, que cortam com peso e força, são instrumentos:", "opcoes": ["Cortocontundentes", "Perfurantes", "Contundentes", "Perfurocortantes"], "explicacao": "Agem pelo gume e pelo peso ao mesmo tempo."}, {"id": 10928, "materia": "ml", "nivel": 3, "enunciado": "Uma faca de ponta enfiada no abdome da vítima provoca ferida:", "opcoes": ["Perfurocortante", "Contusa", "Cortocontusa", "Perfurocontusa"], "explicacao": "Faca de ponta e gume perfura e corta."}, {"id": 10929, "materia": "ml", "nivel": 2, "enunciado": "No cadáver deitado de costas, os livores (manchas roxas) aparecem:", "opcoes": ["Nas partes mais baixas", "Nas partes mais altas", "Somente no rosto", "Somente nas mãos"], "explicacao": "O sangue se acumula pela gravidade."}, {"id": 10930, "materia": "ml", "nivel": 3, "enunciado": "Zona de tatuagem e esfumaçamento ao redor do orifício de entrada indicam tiro dado a:", "opcoes": ["Curta distância", "Longa distância", "Mais de 100 metros", "Qualquer distância"], "explicacao": "Pólvora e fuligem só atingem a pele em disparos próximos."}, {"id": 10931, "materia": "ml", "nivel": 4, "enunciado": "No orifício de entrada de um tiro a distância, costuma haver:", "opcoes": ["Bordas invertidas e orla de escoriação", "Bordas evertidas, irregulares e sem orla alguma", "Bordas lisas e sem nenhuma orla", "Tecidos saindo para fora da ferida"], "explicacao": "As bordas evertidas são típicas do orifício de saída."}, {"id": 10932, "materia": "ml", "nivel": 0, "enunciado": "Nos crimes que deixam vestígios, como a lesão corporal, a prova da materialidade vem do:", "opcoes": ["Exame de corpo de delito", "Depoimento da vítima", "Boletim de ocorrência", "Interrogatório do réu"], "explicacao": "Art. 158 do CPP."}, {"id": 10933, "materia": "ml", "nivel": 4, "enunciado": "O agressor apertou um laço em volta do pescoço da vítima com as próprias forças. Essa asfixia é o:", "opcoes": ["Estrangulamento", "Enforcamento", "Afogamento", "Soterramento"], "explicacao": "No enforcamento quem aperta o laço é o peso do próprio corpo."}, {"id": 10934, "materia": "ml", "nivel": 2, "enunciado": "O laudo diz que o agressor apertou o pescoço da vítima com as mãos até asfixiá-la. É caso de:", "opcoes": ["Esganadura", "Enforcamento", "Estrangulamento", "Sufocação"], "explicacao": "Esganadura: mãos; estrangulamento: laço por força externa; enforcamento: laço pelo peso do corpo."}, {"id": 10935, "materia": "igual", "nivel": 0, "enunciado": "Uma loja se recusou a contratar Jair por causa da cor da pele dele. Isso é:", "opcoes": ["Crime de racismo", "Injúria simples", "Difamação", "Contravenção"], "explicacao": "Lei 7.716/1989."}, {"id": 10936, "materia": "igual", "nivel": 3, "enunciado": "Abordado, Beto ofendeu o policial com um xingamento ligado à raça dele. Hoje, isso é:", "opcoes": ["Injúria racial, como racismo", "Injúria simples, afiançável", "Difamação, de ação privada", "Contravenção penal comum"], "explicacao": "Lei 14.532/2023: a injúria racial passou para a Lei 7.716/1989, inafiançável e imprescritível."}, {"id": 10937, "materia": "igual", "nivel": 4, "enunciado": "No julgamento da ADO 26, o STF enquadrou a homofobia e a transfobia como:", "opcoes": ["Crimes de racismo", "Contravenções penais", "Fatos atípicos", "Injúrias simples"], "explicacao": "Até que o Congresso aprove lei específica."}, {"id": 10938, "materia": "igual", "nivel": 0, "enunciado": "Atender todos com o mesmo respeito, sem distinção de cor, sexo ou religião, é aplicar o princípio da:", "opcoes": ["Igualdade", "Hierarquia", "Anterioridade", "Territorialidade"], "explicacao": "Art. 5º, caput, da Constituição."}, {"id": 10939, "materia": "pcd", "nivel": 0, "enunciado": "Rui, que é cego, quer entrar num shopping com seu cão-guia. Pela lei, ele:", "opcoes": ["Pode entrar com o cão", "Deve deixar o cão fora", "Precisa pagar uma taxa", "Só entra com um vigia"], "explicacao": "Lei 11.126/2005: o cão-guia pode entrar em locais públicos e privados de uso coletivo."}, {"id": 10940, "materia": "pcd", "nivel": 1, "enunciado": "Um restaurante não tem rampa e Tânia, cadeirante, não consegue entrar. Pela LBI, isso é uma barreira:", "opcoes": ["Arquitetônica", "Atitudinal", "Tecnológica", "Nas comunicações"], "explicacao": "Art. 3º, IV, \"b\", da Lei 13.146/2015: barreiras em edifícios públicos e privados."}, {"id": 10941, "materia": "pcd", "nivel": 3, "enunciado": "Pela LBI, a barreira atitudinal é:", "opcoes": ["Comportamento que impede a participação", "Obstáculo físico em calçadas, prédios e praças", "Falta de rampa em transporte público", "Falta de intérprete de Libras em aula"], "explicacao": "Art. 3º, IV, \"e\", da Lei 13.146/2015."}, {"id": 10942, "materia": "pcd", "nivel": 4, "enunciado": "Pela LBI, a avaliação da deficiência, quando necessária, é:", "opcoes": ["Biopsicossocial e multiprofissional", "Somente médica, feita por um perito", "Feita pelo próprio interessado", "Feita só pelo juiz da comarca"], "explicacao": "Art. 2º, § 1º, da Lei 13.146/2015."}, {"id": 10943, "materia": "ia", "nivel": 1, "enunciado": "Um sistema que aprende padrões analisando muitos dados, sem ser programado regra por regra, usa:", "opcoes": ["Aprendizado de máquina", "Planilha eletrônica", "Antivírus", "Backup"], "explicacao": "Machine learning é um ramo da inteligência artificial."}, {"id": 10944, "materia": "ia", "nivel": 3, "enunciado": "Um vídeo falso, feito com IA, que imita o rosto e a voz de uma autoridade, é chamado de:", "opcoes": ["Deepfake", "Phishing", "Firewall", "Cookie"], "explicacao": "Deepfakes são usados em golpes e desinformação."}, {"id": 10945, "materia": "sust", "nivel": 0, "enunciado": "Dona Rita juntou o óleo de fritura numa garrafa, em vez de jogá-lo na pia. Ela fez certo porque o óleo na pia:", "opcoes": ["Entope o esgoto", "Limpa os canos", "Não faz mal", "Trata a água"], "explicacao": "O óleo deve ir para pontos de coleta."}, {"id": 10946, "materia": "sust", "nivel": 1, "enunciado": "Ao usar o verso de folhas impressas como rascunho, a delegacia aplica o R de:", "opcoes": ["Reutilizar", "Reciclar", "Recusar", "Repor"], "explicacao": "Reutilizar é usar de novo, sem transformar o material."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes where id < 1000000));
select nivel, count(*) as questoes_novas from public.questoes where id between 10747 and 10946 group by nivel order by nivel;
select public.questoes_versao() as nova_versao;
